    23→
    24→    this.ws.onopen = () => {
    25→      this.connected = true;
    26→      this._updateConnectionStatus(true);
    27→      console.log("[Pioneer] WebSocket connected");
    28→    };
    29→
    30→    this.ws.onclose = () => {
    31→      this.connected = false;
    32→      this._updateConnectionStatus(false);
    33→      console.log("[Pioneer] WebSocket closed, reconnecting...");
    34→      setTimeout(() => this.connect(), this.reconnectDelay);
    35→    };
    36→
    37→    this.ws.onerror = () => {
    38→      this.ws.close();
    39→    };
    40→
    41→    this.ws.onmessage = (event) => {
    42→      const msg = JSON.parse(event.data);
    43→
    44→      if (msg.type === "full_state") {
    45→        for (const [ch, state] of Object.entries(msg.decks)) {
    46→          this.decks[ch] = state;
    47→          this._updateDeckUI(parseInt(ch), state);
    48→        }
    49→        this._updateRawDataPanel();
    50→      } else if (msg.type === "deck_update") {
    51→        this.decks[msg.channel] = msg.data;
    52→        this._updateDeckUI(msg.channel, msg.data);
