    22→const timeDisplay = document.getElementById("time-display");
    23→const zoomInBtn = document.getElementById("zoom-in");
    24→const zoomOutBtn = document.getElementById("zoom-out");
    25→const jsonPanel = document.getElementById("json-panel");
