    56→
    57→async function handleFile(file) {
    58→  const ext = file.name.split(".").pop().toLowerCase();
    59→  if (!["wav", "mp3"].includes(ext)) {
    60→    showStatus("Please upload a .wav or .mp3 file", "error");
    61→    return;
    62→  }
    63→
    64→  showStatus(`Uploading ${file.name}...`, "info");
    65→
    66→  const formData = new FormData();
    67→  formData.append("file", file);
    68→
    69→  try {
    70→    const uploadRes = await fetch("/api/upload", {
    71→      method: "POST",
    72→      body: formData,
    73→    });
    74→
    75→    if (!uploadRes.ok) {
    76→      const err = await uploadRes.json();
    77→      showStatus(`Upload failed: ${err.detail}`, "error");
    78→      return;
    79→    }
    80→
    81→    const { track_id } = await uploadRes.json();
    82→    currentTrackId = track_id;
    83→
    84→    showStatus(`Analyzing ${file.name}... This may take 30-90 seconds.`, "info");
    85→    analyzeSection.style.display = "block";
    86→    resultsSection.style.display = "none";
    87→
    88→    // Set audio source immediately so user can listen while waiting
    89→    audioEl.src = `/api/audio/${track_id}`;
    90→
    91→    const analyzeRes = await fetch(`/api/analyze/${track_id}`, {
    92→      method: "POST",
    93→    });
    94→
    95→    if (!analyzeRes.ok) {
    96→      const err = await analyzeRes.json();
    97→      showStatus(`Analysis failed: ${err.detail}`, "error");
    98→      return;
    99→    }
   100→
   101→    analysisResult = await analyzeRes.json();
   102→    displayResults(analysisResult);
